-- A `numeric` is a varlena of two bytes a base-10000 digit under a four-byte header when
-- its weight is past ±64: 2 000 significant digits is 1 008 bytes, and beside it 1 684
-- characters of text holds.
-- @setup
CREATE TABLE t (n numeric, a text);
CREATE INDEX t_i ON t (n, a);
INSERT INTO t VALUES (, '');
-- @test
SELECT length(n::text), length(a) FROM t;
